# -*- coding: utf-8 -*-
"""Residentado Médico 2020 · Prueba A (especialidades mezcladas), preguntas 51-70"""
import lote08_base as B
L = []
HAR = "Harrison Principios de Medicina Interna 22.ª ed. (2025)"
NEL = "Nelson Tratado de Pediatría 22.ª ed. (2024)"
SAB = "Sabiston Tratado de Cirugía 22.ª ed. (Elsevier, 2025)"
def Q(n, tema, cat, c, f, nota=None, **kw): B.hacer(L, "PRUEBA_A", n, tema, cat, c, f, nota, **kw)

Q(51, "Neumotórax espontáneo primario", "Patología pleural",
  'El neumotórax espontáneo primario aparece en varones jóvenes, altos y delgados, fumadores, por rotura de bullas o blebs subpleurales, a menudo durante un esfuerzo como un acceso de tos. El aire que ocupa el espacio pleural explica el dolor pleurítico súbito, la taquipnea y el examen típico del hemitórax afectado: vibraciones vocales disminuidas, hipersonoridad y murmullo vesicular abolido o disminuido. En este paciente no hay hipotensión, desviación traqueal ni ingurgitación yugular, por lo que no se trata de un neumotórax hipertensivo, que es una urgencia clínica con compromiso hemodinámico. El derrame pleural y el hemotórax dan matidez y no hipersonoridad; la tromboembolia pulmonar suele cursar con examen pulmonar normal, hipoxemia y factores de riesgo trombóticos. El diagnóstico se confirma con radiografía de tórax en espiración o ecografía. La guía conjunta ERS/EACTS/ESTS de 2024 recomienda, en el neumotórax primario, observación en pacientes estables con pocos síntomas, y cuando se requiere drenar, preferir la aspiración con aguja al tubo torácico; propone además cirugía precoz (VATS con bullectomía) para quienes priorizan evitar recurrencias, que son frecuentes. Perla: sin inestabilidad hemodinámica, el neumotórax primario no es hipertensivo aunque ocupe gran parte del hemitórax.',
  'Walker S et al. Eur Respir J 2024;63:2300797 (guía conjunta ERS/EACTS/ESTS de neumotórax espontáneo); Jouneau S et al. Respir Med Res 2023;83:100999 (guías francesas de neumotórax espontáneo primario); ' + HAR,
  a="neumologia")

Q(52, "Ictericia neonatal precoz por incompatibilidad ABO", "Neonatología",
  'La ictericia que se inicia en las primeras 24 horas de vida nunca es fisiológica y obliga a descartar hemólisis. Una madre O Rh negativo sin embarazos previos tiene riesgo mínimo de aloinmunización Rh, que requiere sensibilización previa; en cambio, la madre del grupo O posee anticuerpos IgG anti-A y anti-B que atraviesan la placenta desde el primer embarazo y pueden hemolizar los eritrocitos de un recién nacido del grupo A o B. Por eso la incompatibilidad ABO afecta al primogénito y es la causa más probable. La hemólisis produce hiperbilirrubinemia indirecta de aparición precoz, con reticulocitosis, anemia leve y prueba de Coombs directa positiva débil o negativa. La bilirrubina directa de 0,9 mg/dl es menos del 20 % de la total y descarta colestasis, por lo que no corresponde a atresia biliar ni al hipotiroidismo, cuyas ictericias son tardías y prolongadas. La guía de la Academia Americana de Pediatría de 2022 plantea que la hemólisis es un factor de riesgo de neurotoxicidad que reduce los umbrales de fototerapia, de modo que se debe medir la bilirrubina de forma seriada y comparar con el nomograma por horas de vida y edad gestacional. Perla: ictericia en las primeras 24 horas más madre O equivale a ABO hasta demostrar lo contrario.',
  'Kemper AR et al. Pediatrics 2022;150:e2022058859 (guía AAP de hiperbilirrubinemia en recién nacidos de 35 semanas o más; solo se accedió a la referencia bibliográfica); ' + NEL,
  a="pediatria")

Q(53, "Triángulo de solubilidad de la bilis", "Litiasis biliar",
  'La bilis es una solución micelar en la que el colesterol, que es casi insoluble en agua, se mantiene disuelto gracias a las sales biliares y a los fosfolípidos, principalmente lecitina. El triángulo de Admirand y Small representa la proporción de estos tres componentes y delimita la zona en que el colesterol permanece en solución micelar; fuera de ella la bilis queda sobresaturada y precipita. Por eso el tercer componente, y el más importante en la litogénesis, es el colesterol. La litiasis de colesterol, que es la forma más frecuente de cálculos en Occidente y en la población andina, requiere sobresaturación de la bilis con colesterol, nucleación acelerada por moco y proteínas, y estasis vesicular. Una revisión de 2023 señala que la prevalencia de la litiasis de colesterol aumenta con la obesidad y la resistencia a la insulina, y que la reducción de los fosfolípidos biliares favorece la cristalización del colesterol. Fosfato, oxalato, calcio y ferritina no forman parte del triángulo: el calcio interviene en los cálculos pigmentarios, junto con la bilirrubina no conjugada, en hemólisis crónica y cirrosis. Perla: más colesterol, menos sales biliares y menos lecitina significan bilis litogénica.',
  'Wang HH et al. Adv Ther 2023;40:743-768 (fosfolípidos biliares y cristalización del colesterol); GPC N.º 11 EsSalud-IETSI de colelitiasis, colecistitis y coledocolitiasis (2018); ' + SAB,
  a="gastroenterologia")

Q(54, "Pulso paradójico en el taponamiento cardiaco", "Cardiopatías",
  'El cuadro de dolor torácico intenso, hipotensión, taquicardia, ingurgitación yugular y ruidos cardiacos apagados corresponde a la tríada de Beck del taponamiento cardiaco, es decir, a la compresión de las cavidades por líquido o sangre en el pericardio; aquí el contexto sugiere pericarditis o, por el dolor migratorio de 10/10, disección aórtica con hemopericardio. Que la ingurgitación yugular aumente con la inspiración es el signo de Kussmaul, frecuente en la compresión pericárdica. En el taponamiento la presión intrapericárdica elevada limita el llenado ventricular; durante la inspiración el retorno venoso al corazón derecho aumenta, el tabique interventricular se desplaza hacia la izquierda y disminuye el volumen sistólico del ventrículo izquierdo, de modo que la presión sistólica cae más de 10 mmHg: es el pulso paradójico. El pulso celer aparece en la insuficiencia aórtica, el tardus y parvus en la estenosis aórtica y el dícroto en la miocardiopatía dilatada con bajo gasto. Una revisión de 2023 destaca que el diagnóstico es clínico y se confirma con ecocardiograma, y que el tratamiento es la pericardiocentesis guiada por eco, con cirugía si hay disección aórtica o trauma. Perla: hipotensión, yugulares ingurgitadas y ruidos apagados exigen ecocardiograma inmediato.',
  'Adler Y et al. Nat Rev Dis Primers 2023;9:36 (taponamiento cardiaco); Schulz-Menger J et al. Eur Heart J 2025;46:3952-4041 (guía ESC 2025 de miocarditis y pericarditis; no se pudo acceder al texto); ' + HAR,
  a="cardiologia")

Q(55, "Indicación quirúrgica más frecuente en la enfermedad de Crohn", "Enfermedad inflamatoria intestinal",
  'La enfermedad de Crohn es una inflamación transmural y discontinua que puede afectar cualquier segmento del tubo digestivo, con predilección por el íleon terminal. Con el tiempo la inflamación transmural evoluciona a fibrosis, estenosis, fístulas y abscesos, de modo que el fenotipo penetrante y estenosante condiciona la necesidad de operar. La causa más común de cirugía es la obstrucción intestinal por estenosis fibrosa refractaria o recurrente, tratada con resección limitada o estricturoplastia; la resección ileocecal es el procedimiento más habitual. Las fístulas y los abscesos son indicaciones frecuentes, pero menos que la obstrucción: los abscesos se manejan primero con drenaje percutáneo y antibióticos, y las fístulas dependen de su tipo y de los síntomas. El carcinoma y la hemorragia masiva son indicaciones infrecuentes. Las guías de 2024 (ECCO, dedicada al tratamiento quirúrgico) y de 2025 (ACG) sustentan la selección del momento de la cirugía y la terapia posoperatoria para prevenir la recurrencia, sobre todo en el íleon anastomosado, donde la endoscopia a los 6 a 12 meses guía el tratamiento. Perla: dejar de fumar es la medida individual más eficaz para reducir la recurrencia posoperatoria.',
  'Adamina M et al. J Crohns Colitis 2024;18:1556-82 (guía ECCO de tratamiento quirúrgico de la enfermedad de Crohn); Lichtenstein GR et al. Am J Gastroenterol 2025;120:1225-64 (guía ACG de enfermedad de Crohn en adultos); ' + SAB,
  nota="Las guías ECCO 2024 y ACG 2025 solo se consultaron en resumen y referencia; los datos concretos del comentario proceden de conocimiento clásico de la enfermedad.",
  a="gastroenterologia")

Q(56, "Isquemia mesentérica aguda", "Abdomen agudo",
  'Un paciente con prótesis valvular aórtica tiene riesgo de embolia arterial, ya sea por trombos de la válvula, por fibrilación auricular o por anticoagulación insuficiente. La embolia a la arteria mesentérica superior produce isquemia mesentérica aguda, que se manifiesta con dolor cólico abdominal intenso desproporcionado frente a un examen físico inicialmente pobre, náuseas, vómitos y diarrea por hiperperistaltismo, y después íleo, peritonitis, acidosis láctica y leucocitosis. La clave es pensar en ella en todo paciente con arritmia o cardiopatía embolígena y dolor abdominal severo. La neoplasia de intestino delgado y la enfermedad de Crohn evolucionan en días o semanas; la colitis ulcerosa produce diarrea sanguinolenta y dolor en hemiabdomen izquierdo; la obstrucción de intestino delgado cursa con distensión y ausencia de gases, no con diarrea. Las guías de la ESVS de 2025 tratan por separado la isquemia mesentérica aguda arterial, la no oclusiva y la venosa, y destacan el diagnóstico rápido con angiotomografía y la revascularización precoz, endovascular o abierta, con resección de intestino no viable. Perla: dolor desproporcionado al examen, más cardiopatía embolígena, es isquemia mesentérica hasta demostrar lo contrario.',
  'Koelemay MJW et al. Eur J Vasc Endovasc Surg 2025;70:153-218 (guía ESVS 2025 de enfermedades de arterias y venas mesentéricas y renales; solo se accedió al resumen); Loffroy R et al. Cardiovasc Intervent Radiol 2025;48:1091-1103 (estándares CIRSE de isquemia mesentérica arterial aguda y crónica); ' + SAB,
  a="cirugia")

Q(57, "Mioma uterino en la gestación", "Obstetricia",
  'Los miomas se presentan en una proporción pequeña de gestantes, con prevalencia descrita de 1 a 10,7 %, y la mayoría permanecen asintomáticos y estables, o incluso se reducen después del parto. Un mioma intramural de 5 cm en una gestación normal y asintomática no requiere tratamiento, solo observación con ecografías para vigilar crecimiento fetal, localización placentaria y presentación fetal. La miomectomía durante el embarazo se reserva para situaciones excepcionales, como un mioma pediculado torcido o dolor refractario, porque el útero gestante es muy vascularizado y el riesgo de hemorragia, aborto y parto prematuro es alto; por eso no se justifica operar de inmediato ni a las 34 semanas. La cesárea a las 38 semanas no está indicada solo por un mioma: se decide por criterios obstétricos como la presentación, la placenta previa o la obstrucción del canal del parto. Los análogos de GnRH están contraindicados en la gestación. Un metaanálisis de 2024 con 24 estudios encontró que los miomas aumentan el riesgo de parto pretérmino, cesárea, placenta previa, desprendimiento, hemorragia posparto, presentación podálica y preeclampsia, lo que justifica la vigilancia. Perla: el dolor por degeneración roja se trata con analgésicos y reposo, no con cirugía.',
  'Li H et al. BMC Pregnancy Childbirth 2024;24:345 (metaanálisis de miomas y resultados adversos del embarazo; texto completo); ' + "Williams Obstetricia 26.ª ed. (2022)",
  a="ginecologia")

Q(58, "Vólvulo de sigmoides", "Abdomen agudo",
  'El vólvulo de sigmoides es la torsión del colon sigmoide sobre su mesenterio, con obstrucción en asa cerrada. Es muy frecuente en hombres mayores de zonas de altura como Puno, por dolicomegasigmoide ligado a la dieta rica en fibra y a la altitud. El cuadro es de dolor cólico intenso, gran distensión abdominal asimétrica y timpánica, náuseas, vómitos tardíos y ausencia de gases y heces. El rebote difuso indica irritación peritoneal por sufrimiento isquémico del asa y obliga a la laparotomía urgente, mientras que la descompresión endoscópica se reserva para pacientes sin peritonitis ni gangrena. La apendicitis perforada y la diverticulitis cursan con dolor localizado y fiebre, pero no con distensión masiva de ese tipo; la obstrucción yeyunal y la intususcepción ileal dan niveles hidroaéreos centrales y vómitos precoces. El consenso WSES de 2023 recomienda, tras la destorsión endoscópica exitosa, resecar el sigmoides durante el mismo ingreso, porque la recurrencia tras la destorsión sola oscila entre 43 y 75 %, y cada nuevo episodio añade riesgo de isquemia y perforación. Perla: la radiografía con asa en grano de café sin signos peritoneales permite intentar primero la destorsión.',
  'Tian BWCA et al. World J Emerg Surg 2023;18:34 (consenso WSES de vólvulo de sigmoides; texto completo); ' + SAB,
  a="cirugia")

Q(59, "Fronesis en bioética", "Bioética",
  'La fronesis es el término aristotélico para la sabiduría práctica, la virtud intelectual que permite deliberar bien y elegir, en una situación concreta y con información incompleta, el curso de acción moralmente más adecuado. En bioética neonatal es particularmente importante porque las decisiones sobre reanimación o limitación de tratamiento en recién nacidos muy prematuros o con malformaciones graves no pueden resolverse con una regla fija, sino mediante un juicio prudente que pondere el pronóstico, el interés superior del niño, los valores de los padres y los recursos disponibles. Por contraste, la integridad es la coherencia entre valores y conducta, la solidaridad es la responsabilidad compartida frente a la vulnerabilidad del otro, la fortaleza (valentía) es la virtud de sostener la decisión correcta pese al temor, y la templanza es la moderación del deseo. La ética de las virtudes sostiene que la sabiduría práctica es una competencia que se desarrolla con la experiencia y la reflexión, y un trabajo de 2025 la describe como una pericia ética transversal a las situaciones clínicas. Perla: no existe fronesis sin experiencia clínica, deliberación y reflexión sobre la propia práctica.',
  'De Caro M et al. J Med Philos 2025;50:80-92 (sabiduría práctica como pericia ética en la práctica médica; solo se accedió al título y la referencia); ' + NEL,
  nota="No se halló una guía vigente específica sobre el término; el comentario se limita a la definición aristotélica y a la fuente citada.",
  a="salud_publica")

Q(60, "Sífilis primaria: chancro duro", "Infecciones de transmisión sexual",
  'La sífilis primaria, causada por Treponema pallidum, comienza tras un periodo de incubación de unas tres semanas con un chancro: úlcera única, indolora, de bordes indurados y fondo limpio, en el sitio de inoculación, acompañada de adenopatía regional no dolorosa que a veces falta, como en este caso. La lesión cura sola en semanas, lo que no significa curación de la infección, que progresa a sífilis secundaria. Una relación sexual hace 7 días es un intervalo corto, por lo que la serología puede ser aún negativa y requiere repetirse; si se dispone de campo oscuro o PCR de la lesión, se puede confirmar. El chancroide por Haemophilus ducreyi produce úlceras dolorosas, blandas y múltiples, con adenopatía supurada; el herpes genital produce vesículas agrupadas dolorosas que se ulceran; el linfogranuloma venéreo se manifiesta con una pápula fugaz y bubones; el absceso de Bartholino es una colección dolorosa en el introito. El tratamiento de la sífilis temprana es una dosis única de penicilina benzatínica 2,4 millones de UI por vía intramuscular, y debe tratarse a la pareja. Perla: úlcera genital indolora e indurada es sífilis hasta demostrar lo contrario.',
  'Norma Técnica de Salud 240-MINSA/DGIESP-2026 de infecciones de transmisión sexual (RM 035-2026-MINSA; solo se cita como referencia vigente); Moseley P et al. Lancet Infect Dis 2024;24:e24-e35 (resurgimiento de la sífilis congénita; solo resumen); Workowski KA et al. MMWR Recomm Rep 2021;70(4):1-187 (guías de ITS de los CDC); ' + HAR,
  nota="No se pudo abrir el texto de la NTS 240-2026 ni las demás fuentes de infecciones de transmisión sexual; el esquema de penicilina benzatínica corresponde al estándar internacional y debe cotejarse con la NTS.",
  a="infectologia")

Q(61, "Transmisión vertical del VIH", "Infecciones perinatales",
  'En la actualidad la principal vía de infección por VIH en el recién nacido es la transmisión vertical, de madre a hijo, que puede ocurrir en el útero, durante el parto o por la lactancia. Sin intervención el riesgo se acerca a 15 o 45 % según el contexto, y es mayor con carga viral materna alta, parto vaginal con viremia, ruptura prolongada de membranas y lactancia. Las otras vías son raras en niños: la transmisión horizontal y la parenteral requieren contacto con sangre infectada, y la transfusión es excepcional desde que se tamiza la sangre. La lactancia materna es parte de la transmisión vertical, pero no es su forma principal en países que indican sucedáneos. La estrategia de eliminación se basa en el tamizaje de toda gestante, el tratamiento antirretroviral temprano para lograr carga viral indetectable, la profilaxis antirretroviral del recién nacido y el reemplazo de la leche materna. Una revisión de 2023 describe cómo los ensayos clínicos permitieron reducir la transmisión de cerca del 25 % a cifras muy bajas, y la norma peruana establece la prevención de la transmisión materno infantil de VIH, sífilis y hepatitis B. Perla: carga viral materna indetectable al parto reduce el riesgo de transmisión a menos del 1 %.',
  'Cardenas MC et al. Viruses 2023;15:849 (prevención de la transmisión vertical del VIH; texto completo); Norma Técnica de Salud 159-MINSA/2019/DGIESP (transmisión materno infantil de VIH, sífilis y hepatitis B); NTS 169-MINSA/2020/DGIESP (VIH); ' + NEL,
  a="infectologia")

Q(62, "Colecistitis aguda litiásica", "Vía biliar",
  'La colecistitis aguda litiásica resulta de la obstrucción del conducto cístico por un cálculo, con inflamación de la pared vesicular y sobreinfección secundaria. Se presenta con dolor en hipocondrio derecho, náuseas y vómitos, signo de Murphy positivo, fiebre y leucocitosis. Según los criterios de Tokio de 2018, el diagnóstico exige un signo local (Murphy o dolor en hipocondrio derecho), un signo sistémico (fiebre, leucocitosis o proteína C reactiva elevada) y confirmación por imagen, sobre todo ecográfica. Una ictericia leve con ligera elevación de fosfatasa alcalina y transaminasas puede deberse a la inflamación que comprime el conducto hepático común, sin que haya coledocolitiasis, y se asocia al síndrome de Mirizzi si es marcada. La colangitis exige la tríada de Charcot de fiebre, ictericia y dolor, con colestasis franca; la coledocolitiasis aislada no explica el Murphy ni la leucocitosis; la colecistitis crónica reagudizada no se puede distinguir en la fase aguda y su manejo es el mismo; y la gastritis aguda no tiene signos peritoneales. El tratamiento es la colecistectomía laparoscópica temprana con antibióticos. Perla: Murphy más leucocitosis más fiebre define la colecistitis; la ictericia marcada obliga a descartar coledocolitiasis o Mirizzi.',
  'Yokoe M et al. J Hepatobiliary Pancreat Sci 2018;25:41-54 (criterios de Tokio 2018, colecistitis); Barie PS et al. Surg Infect 2023;24:99-111 (colecistitis no complicada: infección o inflamación; solo resumen); GPC N.º 11 EsSalud-IETSI (2018); ' + SAB,
  a="gastroenterologia")

Q(63, "Caput succedaneum", "Neonatología",
  'El caput succedaneum es un edema serosanguinolento del tejido subcutáneo del cuero cabelludo, por encima del periostio, causado por la presión del canal de parto sobre la presentación cefálica. Está presente al nacer, es de bordes mal definidos, puede acompañarse de equimosis y petequias, atraviesa las suturas craneales y se resuelve de forma espontánea en pocos días. En este recién nacido el aumento de volumen con edema y equimosis frontal y parietal bilateral concuerda con ese cuadro. El cefalohematoma es una colección de sangre subperióstica limitada por una sutura, que no cruza la línea media, aparece de horas a días después del parto y puede tardar semanas en resolverse; se asocia a la ictericia por reabsorción de la sangre. El mielomeningocele es un defecto del tubo neural que se ve en el dorso, no en el cuero cabelludo; la deformación plástica de los parietales modifica la forma de la cabeza, sin edema, y se corrige sola; la meningitis neonatal produce fiebre o hipotermia, irritabilidad y fontanela abombada. No se requiere tratamiento, solo observación y tranquilizar a los padres. Perla: si la tumefacción cruza una sutura es caput, y si se limita a un hueso es cefalohematoma.',
  NEL + ' (capítulos de traumatismo obstétrico del recién nacido)',
  nota="Solo se cita Nelson 22.ª ed. (2024) como fuente de 2023-2026; no se halló guía vigente específica sobre esta lesión benigna del recién nacido.",
  a="pediatria")

Q(64, "Serotonina y trastornos del ánimo", "Trastornos afectivos",
  'La hipótesis monoaminérgica de la depresión postula que el déficit de serotonina, noradrenalina y dopamina en la sinapsis participa en la génesis de los trastornos del ánimo, y esta es la base farmacológica de los inhibidores selectivos de la recaptación de serotonina (ISRS) y de los inhibidores de la recaptación de serotonina y noradrenalina (IRSN), que son fármacos de primera línea en el trastorno depresivo mayor. En la pregunta, la serotonina es el neurotransmisor clásicamente vinculado con el estado de ánimo, la ansiedad, el sueño y el apetito. La glicina y el glutamato son neurotransmisores inhibitorio y excitatorio de la médula y la corteza; la dopamina se asocia a motivación, recompensa y psicosis; la acetilcolina, a memoria y cognición. La evidencia actual matiza el papel causal de la serotonina: una revisión sistemática paraguas de 2023 concluyó que no hay evidencia consistente de que la depresión se deba a una menor actividad o concentración de serotonina, aunque el sistema serotoninérgico sigue siendo diana de tratamiento. La guía CANMAT 2023 y la guía peruana de depresión (RM 136-2023/MINSA) mantienen los antidepresivos junto con psicoterapia como base del manejo. Perla: los ISRS actúan sobre un sistema implicado en el estado de ánimo, aunque su eficacia no demuestra un déficit simple de serotonina.',
  'Moncrieff J et al. Mol Psychiatry 2023;28:3243-56 (revisión paraguas de la teoría de la serotonina; texto completo); Lam RW et al. Can J Psychiatry 2024;69:641-87 (guía CANMAT 2023 de trastorno depresivo mayor; texto completo); RM 136-2023/MINSA (GPC de depresión en mayores de 18 años, primer nivel); ' + "Katzung Farmacología básica y clínica 16.ª ed. (2024)",
  nota="La clave oficial (serotonina) se mantiene; la evidencia actual (Moncrieff 2023) cuestiona que la depresión se deba a un déficit simple de serotonina, aunque sigue siendo el neurotransmisor clásicamente asociado.",
  a="psiquiatria")

Q(65, "Estudio de cohortes", "Epidemiología",
  'Un estudio de cohortes sigue a un grupo de personas libres del evento de interés y registra la exposición al inicio; luego los observa durante un tiempo para medir la aparición de la enfermedad. Aquí se reclutan presos que ingresan sin anticuerpos anti VIH, se les interroga sobre conductas de riesgo (exposición) y se repite la prueba cada seis meses para detectar seroconversión (resultado). Es un seguimiento longitudinal prospectivo de personas sin la enfermedad al inicio, de modo que permite calcular incidencia y riesgo relativo, que es el sello de la cohorte. El estudio de casos y controles parte de personas con la enfermedad y las compara con controles sin ella, buscando la exposición pasada; el cuasiexperimental asigna una intervención sin aleatorización y aquí no se interviene; el descriptivo solo caracteriza frecuencias; el transversal mide exposición y enfermedad al mismo tiempo, sin seguimiento. Una revisión de 2024 sobre diseños de estudios clínicos subraya que los estudios de cohortes observan al grupo a lo largo del tiempo y pueden ser prospectivos o retrospectivos, con la ventaja de establecer secuencia temporal entre exposición y evento. Perla: seguimiento de personas sanas expuestas hasta que aparece la enfermedad es cohorte; parte de la enfermedad hacia atrás es casos y controles.',
  'Kim S, Kim J. Clin Exp Emerg Med 2024;11:33-42 (panorama de diseños de estudios clínicos; texto completo); ' + "Gordis Epidemiología 6.ª ed. (2019)",
  a="salud_publica")

Q(66, "Tórax inestable con insuficiencia respiratoria", "Trauma torácico",
  'El tórax inestable se define por fracturas costales de al menos tres costillas consecutivas, cada una en dos puntos, que forman un segmento que se mueve de modo paradójico con la respiración. Este paciente tiene fracturas bilaterales, movimientos paradójicos, disnea intensa, cianosis e hipoventilación, es decir, insuficiencia respiratoria. La mayor parte de la morbilidad no proviene del segmento flotante sino de la contusión pulmonar subyacente, del dolor que limita la ventilación y de la atelectasia. La prioridad del ATLS es A, B y C: asegurar la vía aérea y la ventilación, por lo que la indicación más apropiada es la intubación con ventilación mecánica, que actúa como férula neumática interna. La broncoscopía no soluciona la mecánica ventilatoria; la toracostomía se indica si hay neumotórax o hemotórax, que no se describen; la cricotiroidotomía es una vía aérea quirúrgica de rescate si fracasa la intubación; y la fijación costal es un tratamiento posterior en pacientes seleccionados. El posicionamiento de la WSES y la CWIS de 2024 considera la estabilización quirúrgica en el tórax inestable y en fracturas múltiples desplazadas, junto con analgesia multimodal, fisioterapia y ventilación cuando es necesaria. Perla: tórax inestable con hipoxemia necesita ventilación; la fijación costal puede esperar.',
  'Sermonesi G et al. World J Emerg Surg 2024;19:33 (posicionamiento WSES y CWIS de estabilización quirúrgica de fracturas costales; texto completo); ' + SAB + '; ATLS 10.ª ed. del American College of Surgeons (2018)',
  a="cirugia")

Q(67, "Displasia broncopulmonar en el prematuro extremo", "Neonatología",
  'La displasia broncopulmonar es la complicación respiratoria crónica del recién nacido muy prematuro. Su base es la inmadurez pulmonar, con déficit de surfactante y desarrollo alveolar incompleto, agravada por la ventilación mecánica, el oxígeno, la inflamación, las infecciones y la persistencia del conducto arterioso. El resultado es una detención de la septación alveolar con menor superficie de intercambio. Se define por la necesidad de oxígeno o soporte respiratorio a las 36 semanas de edad posmenstrual en los nacidos antes de las 32 semanas. En los prematuros de extremado bajo peso es la complicación más frecuente a largo plazo: una revisión de 2024 la considera la complicación a largo plazo más común del nacimiento extremadamente prematuro, con consecuencias multisistémicas de por vida, y señala que los avances en cuidados neonatales no redujeron su incidencia. Las otras opciones son importantes pero menos frecuentes en conjunto: la hemorragia intraventricular afecta a una proporción considerable de los menores de 28 semanas, la enterocolitis necrotizante a una proporción menor y el conducto arterioso persistente es frecuente pero se trata de una cardiopatía y no de una complicación pulmonar crónica. La prevención incluye ventilación no invasiva, surfactante menos invasivo, cafeína y corticoides prenatales. Perla: cuanto menor la edad gestacional, mayor la probabilidad de displasia broncopulmonar.',
  'Durlak W, Thébaud B. Neonatology 2024;121:596-607 (prevención y tratamiento de la displasia broncopulmonar; solo resumen); ' + NEL,
  a="pediatria")

Q(68, "Acalasia", "Motilidad esofágica",
  'La acalasia es un trastorno motor del esófago por degeneración inflamatoria de las neuronas inhibidoras del plexo mioentérico, que causa falta de relajación del esfínter esofágico inferior y ausencia de peristaltismo del cuerpo esofágico. Se manifiesta con disfagia tanto a sólidos como a líquidos, regurgitación, dolor torácico y pérdida de peso. Una manometría de alta resolución con ausencia de peristaltismo y relajación incompleta del esfínter, como en este paciente, confirma el diagnóstico; la clasificación de Chicago 4.0 de 2021 la subdivide en tres tipos según el patrón de presurización. Las alternativas fallan por esto: el espasmo difuso conserva la relajación del esfínter con contracciones prematuras; el cáncer esofágico se diagnostica por endoscopia y puede simular acalasia como pseudoacalasia; el síndrome de Plummer-Vinson combina disfagia alta con anemia ferropénica y membranas esofágicas; el esófago de Barrett es una metaplasia por reflujo. Una revisión de 2025 indica que el diagnóstico se sostiene en el esofagograma con bario, la manometría de alta resolución y la endoscopia, y el tratamiento incluye dilatación neumática, miotomía de Heller o miotomía endoscópica peroral (POEM). Perla: pico de ave en el esofagograma con bario más manometría sin relajación del esfínter equivale a acalasia.',
  'Provenza CG, Romanelli JR. Surg Clin North Am 2025;105:143-58 (acalasia: diagnóstico y tratamiento; solo resumen); Yadlapati R et al. Neurogastroenterol Motil 2021;33:e14058 (clasificación de Chicago 4.0); Calabrese EC et al. Surg Endosc 2025;39:4027-37 (actualización 2024 de las guías SAGES de POEM); ' + SAB,
  a="gastroenterologia")

Q(69, "Factor de riesgo de endometritis puerperal", "Puerperio",
  'La endometritis puerperal es una infección polimicrobiana de la decidua y el miometrio, causada por flora vaginal y cervical ascendente (anaerobios, estreptococos, enterobacterias), que se manifiesta con fiebre, dolor uterino, subinvolución y loquios fétidos en los primeros días después del parto. El factor de riesgo más importante es la cesárea, porque la incisión uterina, el tejido desvitalizado, los cuerpos extraños de sutura y la contaminación por flora cérvico-vaginal durante la intervención favorecen la infección; el riesgo es varias veces mayor que tras un parto vaginal, sobre todo si la cesárea es de urgencia o tras trabajo de parto con ruptura de membranas. Los demás factores (trabajo de parto prolongado, tactos vaginales repetidos, corioamnionitis, embarazo gemelar) contribuyen de forma menor, y la placenta previa lo hace por mayor frecuencia de cesárea. Una revisión de 2026 clasifica la endometritis posparto como infección de sitio quirúrgico de órgano o espacio tras una cesárea, entre las infecciones poscesárea que se describen en 3 a 15 % de los casos. La prevención se basa en la profilaxis con cefazolina antes de la incisión, la antisepsia vaginal en cesárea con trabajo de parto, y el tratamiento es clindamicina con gentamicina. Perla: toda fiebre posterior a la cesárea con dolor uterino es endometritis hasta demostrar lo contrario.',
  'Hayasaka M et al. Am J Obstet Gynecol 2026;233:S524-S540 (infecciones del sitio quirúrgico tras cesárea; solo resumen); ' + HAR,
  nota="La revisión AJOG 2026 solo se leyó en resumen; las cifras del riesgo relativo proceden del conocimiento clásico y no se atribuyen a la fuente.",
  a="ginecologia")

Q(70, "Estado de portador de Streptococcus del grupo A", "Microbiología",
  'El estado de portador faríngeo de Streptococcus pyogenes (grupo A) es la colonización asintomática de la faringe, sin respuesta inflamatoria ni infección activa, y es frecuente en escolares. Estos portadores tienen una carga bacteriana baja y rara vez transmiten el germen, por lo que se consideran de bajo riesgo contagioso y no suelen requerir tratamiento ni exclusión escolar. Esto cambia el enfoque de la faringitis: se trata a quien tiene la infección aguda para prevenir la fiebre reumática, mientras que a los portadores asintomáticos no se les erradica de manera rutinaria. Una revisión sistemática de 2024 evaluó los antibióticos para erradicar el estado de portador faríngeo de S. pyogenes en personas asintomáticas, lo que refleja que la erradicación se considera una intervención excepcional. En cambio, los otros microorganismos sí son contagiosos en el estado de portador o de eliminación: el virus sincitial respiratorio se elimina por vía respiratoria durante días o semanas; el virus herpes simple se excreta de forma asintomática por piel y mucosas; algunas cepas de Escherichia coli, como las enterohemorrágicas, se transmiten por portadores fecales; y Chlamydia trachomatis genital asintomática es la fuente principal de transmisión sexual. Perla: el portador faríngeo de estreptococo del grupo A es el ejemplo clásico de portador no contagioso.',
  'Hung TY et al. J Infect 2024;88:106104 (antibióticos para erradicar el estado de portador faríngeo de Streptococcus pyogenes en personas asintomáticas; solo resumen); ' + HAR,
  nota="La afirmación de bajo riesgo de transmisión del portador es de conocimiento clásico (Harrison); la revisión de 2024 solo se leyó en resumen y no se le atribuyen datos.",
  a="infectologia")
